"""Render L0 (MEMORY.md) and L1 from items, within the L0 budget (DESIGN §4, §4.1)."""

from __future__ import annotations

import collections
import dataclasses
import re
from dataclasses import dataclass
from typing import Iterable, Optional, Sequence

from .items import DEFAULT_SECTION, Item, PendingEntry
from .segments import OVERFLOW, UNRESOLVED, l1_heading, norm, pieces
from .store import Config
from .text import SEPARATOR, sanitize, split_segments

TITLE = "# Memory Index"
NOTE = (
    "> Generated by cc-memory-index from each memory file's frontmatter. You may still add a line here:"
    " it will be moved into that memory file automatically. Other memories are in the file linked below."
)
L1_TITLE = "# Memory Index — on demand"
L1_DESCRIPTION = "Generated index of memories that are not loaded every session — do not edit by hand"
L1_NOTE = "Generated by cc-memory-index from each memory file's frontmatter: edit the memory files, not this file."
BULLET = "- "
_WARNING_COUNT = re.compile(r"- Warning: ([0-9]{1,9}) ")


class BudgetError(Exception):
    """The fixed part of L0 does not fit the budget (exit 2)."""


class RenderInvariant(Exception):
    """The rendered output broke an invariant; nothing may be written (exit 8)."""


@dataclass(frozen=True)
class Rendered:
    l0: str
    l1: str
    overflow: list[Item]
    oversized: list[Item]
    unresolved: list[Item]


def link_line(l1_name: str) -> str:
    return (
        f"- Not loaded every session: [{l1_name}]({l1_name}) lists every other memory"
        " — open it when you need something not listed here."
    )


def warning_line(count: int, l1_name: str) -> str:
    return (
        f"- Warning: {count} resident entries did not fit the index budget and are listed under"
        f' "{OVERFLOW}" in {l1_name}. Run `cc-memory-index suggest`.'
    )


def is_warning_line(line: str, l1_names: Iterable[str]) -> bool:
    """True for the budget warning line naming one of l1_names, whatever its count (normalised)."""
    text = norm(line)
    m = _WARNING_COUNT.match(text)
    return m is not None and any(text == norm(warning_line(int(m.group(1)), name)) for name in l1_names)


def nbytes(s: str) -> int:
    return len(s.encode("utf-8"))


def size_of(lines: Sequence[str]) -> int:
    """Bytes of lines written one per line, each ending with LF."""
    return sum(nbytes(line) + 1 for line in lines)


def render_order(items: Iterable[Item]) -> list[Item]:
    """Sections by smallest order then name; the unnamed subsection first, then the others
    the same way; items by (order, file). Ties keep the input order."""
    items = list(items)
    section_min: dict[str, int] = {}
    sub_min: dict[tuple[str, str], int] = {}
    for it in items:
        section_min[it.section] = min(section_min.get(it.section, it.order), it.order)
        sub = (it.section, it.sub)
        sub_min[sub] = min(sub_min.get(sub, it.order), it.order)

    def key(it: Item) -> tuple[int, str, bool, int, str, int, str]:
        return (section_min[it.section], it.section, it.sub != "", sub_min[(it.section, it.sub)],
                it.sub, it.order, it.file or "")

    return sorted(items, key=key)


def packable(idx: str) -> bool:
    """True when idx stays one segment next to others: no top-level ' · ', brackets closed."""
    return split_segments(idx + SEPARATOR + "x") == [idx, "x"]


class Body:
    """The sectioned part of L0 or L1. size and len(lines) are kept exact as items are added."""

    def __init__(self, line_max: int) -> None:
        self.lines: list[str] = []
        self.size = 0
        self._line_max = line_max
        self._section: Optional[str] = None
        self._sub: Optional[str] = None
        self._open = 0
        self._joinable = False

    def plan(self, item: Item) -> tuple[list[str], str]:
        """New lines to append for item, or ([], text) to join onto the open line."""
        new_section = item.section != self._section
        head: list[str] = ["", "## " + item.section] if new_section else []
        if new_section or item.sub != self._sub:
            head += ["", "### " + item.sub, ""] if item.sub else [""]
        else:
            join = SEPARATOR + item.idx
            if self._joinable and packable(item.idx) and self._open + nbytes(join) <= self._line_max:
                return [], join
        return head + [BULLET + item.idx], ""

    @staticmethod
    def cost(plan: tuple[list[str], str]) -> tuple[int, int]:
        lines, join = plan
        return size_of(lines) + nbytes(join), len(lines)

    def apply(self, item: Item, plan: tuple[list[str], str]) -> None:
        lines, join = plan
        self.size += self.cost(plan)[0]
        if join:
            self.lines[-1] += join
            self._open += nbytes(join)
            return
        self.lines.extend(lines)
        self._section, self._sub = item.section, item.sub
        self._open = nbytes(lines[-1])
        self._joinable = packable(item.idx)

    def add(self, item: Item) -> None:
        self.apply(item, self.plan(item))


def _clean_line(line: str) -> str:
    body = sanitize(line)
    return " " * (len(line) - len(line.lstrip(" \t"))) + body if body else ""


def preamble_lines(preamble: Optional[str]) -> list[str]:
    """The manual preamble as written to L0, or the default one when it is none or blank."""
    lines = [_clean_line(line) for line in (preamble or "").splitlines()]
    while lines and not lines[0]:
        lines.pop(0)
    while lines and not lines[-1]:
        lines.pop()
    return lines or [TITLE, "", NOTE]


def head_lines(preamble: Optional[str], l1_name: str) -> list[str]:
    """Preamble, a blank line and the L1 link line."""
    return preamble_lines(preamble) + ["", link_line(l1_name)]


def check_fixed_cost(head: list[str], reserve: str, cfg: Config) -> None:
    """DESIGN §4.1 step 1: head, reserved warning and one maximum-size item must fit."""
    probe = ["", "## " + DEFAULT_SECTION, "", BULLET + "x" * cfg.item_max_bytes]
    lines = head + [reserve] + probe
    size = size_of(lines)
    if size > cfg.budget_bytes or len(lines) > cfg.budget_lines:
        raise BudgetError(
            f"the fixed part of MEMORY.md (preamble, link line, reserved warning line and one item of"
            f" {cfg.item_max_bytes} bytes) needs {size} bytes and {len(lines)} lines, over the budget of"
            f" {cfg.budget_bytes} bytes and {cfg.budget_lines} lines: shorten the preamble or change"
            " .memory-index.json"
        )


@dataclass
class Fill:
    body: Body
    overflow: list[Item]
    oversized: list[Item]


def fill(head: list[str], resident: Sequence[Item], cfg: Config) -> Fill:
    """DESIGN §4.1 steps 1-3: admit resident items in render order while L0 stays in budget.

    The budget counts the head plus the warning line reserved at its maximum length. overflow
    holds every item that is not admitted, in render order; oversized is its over-cap subset.
    """
    reserve = warning_line(len(resident), cfg.l1_name)
    check_fixed_cost(head, reserve, cfg)
    base_size, base_lines = size_of(head) + nbytes(reserve) + 1, len(head) + 1
    result = Fill(Body(cfg.line_max_bytes), [], [])
    body = result.body
    stopped = False
    for item in render_order(resident):
        if nbytes(item.idx) > cfg.item_max_bytes:
            result.oversized.append(item)
        elif not stopped:
            plan = body.plan(item)
            size, lines = Body.cost(plan)
            fits = base_size + body.size + size <= cfg.budget_bytes
            if fits and base_lines + len(body.lines) + lines <= cfg.budget_lines:
                body.apply(item, plan)
                continue
            stopped = True
        result.overflow.append(item)
    return result


def _join(lines: Sequence[str]) -> str:
    return "\n".join(lines) + "\n"


def _l0(head: list[str], filled: Fill, cfg: Config) -> str:
    warning = [warning_line(len(filled.overflow), cfg.l1_name)] if filled.overflow else []
    text = _join(head + warning + filled.body.lines)
    expected = size_of(head + warning) + filled.body.size
    lines = len(head) + len(warning) + len(filled.body.lines)
    if nbytes(text) != expected or text.count("\n") != lines:
        raise RenderInvariant("MEMORY.md does not have the size it was budgeted with")
    if expected > cfg.budget_bytes or lines > cfg.budget_lines:
        raise RenderInvariant("MEMORY.md would exceed its budget")
    return text


def l1_head(l1_name: str) -> list[str]:
    """The fixed start of L1: frontmatter, title and note."""
    return ["---", f"name: {l1_name[: -len('.md')]}", f"description: {L1_DESCRIPTION}", "metadata:",
            "  type: reference", "  generated: true", "---", "", L1_TITLE, "", L1_NOTE]


def _l1(listed: Sequence[Item], overflow: Sequence[Item], unresolved: Sequence[Item], l1_name: str) -> str:
    lines = l1_head(l1_name)
    body = Body(0)
    for item in render_order(listed):
        body.add(dataclasses.replace(item, section=l1_heading(item.section)))
    lines += body.lines
    for title, group in ((OVERFLOW, overflow), (UNRESOLVED, unresolved)):
        if group:
            lines += ["", "## " + title, ""] + [BULLET + item.idx for item in group]
    return _join(lines)


def render(items: Sequence[Item], manual_preamble: Optional[str], cfg: Config) -> Rendered:
    """L0 and L1 for items; deterministic, LF only (DESIGN §4, §4.1)."""
    head = head_lines(manual_preamble, cfg.l1_name)
    resident = [it for it in items if it.resident and it.origin != "pending"]
    listed = [it for it in items if not it.resident and it.origin != "pending"]
    unresolved = [it for it in items if it.origin == "pending"]
    filled = fill(head, resident, cfg)
    l1 = _l1(listed, filled.overflow, unresolved, cfg.l1_name)
    return Rendered(_l0(head, filled, cfg), l1, filled.overflow, filled.oversized, unresolved)


def _listed(rendered: Rendered) -> collections.Counter[str]:
    found: collections.Counter[str] = collections.Counter()
    for text in (rendered.l0, rendered.l1):
        for line in text.split("\n"):
            if line.startswith(BULLET):
                found.update(pieces(line[len(BULLET):]))
    return found


def _label(item: Item) -> str:
    if item.origin == "manual":
        return f"manual line {item.idx[:60]!r}"
    if item.origin == "pending":
        return f"pending line for {item.file}"
    return str(item.file)


def reachable(items: Sequence[Item], rendered: Rendered, pending: Sequence[PendingEntry] = ()) -> list[str]:
    """Items and pending entries whose text is missing from L0 and L1 (DESIGN §4 invariant).

    Each item consumes its own occurrences, so two items with the same text need two lines.
    A pending entry needs only to be present: when it is a file's idx it shares that item's line.
    """
    listed = _listed(rendered)
    left = collections.Counter(listed)
    missing: list[str] = []
    for item in items:
        need = collections.Counter(pieces(item.idx))
        if not need or any(left[s] < n for s, n in need.items()):
            missing.append(_label(item))
        else:
            left.subtract(need)
    for entry in pending:
        segments = pieces(entry.idx)
        if not segments or any(listed[s] == 0 for s in segments):
            missing.append(f"pending line for {entry.file}")
    return missing
